  "help.freeAfterDues": "ఆదాయం మైనస్ పునరావృత మరియు క్రియాశీల బిల్లుల నుండి నెలవారీ బకాయిలను అంచనా వేసింది.",
  "help.dueHeatmap": "తరువాతి నాలుగు వారాల్లో ఎన్ని బిల్లులు వస్తాయి మరియు వాటి మొత్తం మొత్తం.",
  "help.debtTrend": "మా వద్ద స్నాప్ ‌ షాట్ ‌ లు ఉన్న పాత మరియు సరికొత్త నెల మధ్య మొత్తం ఓపెన్ బ్యాలెన్స్ ‌ లో మార్పు.",
  "help.chitInstallments": "చాలా పెద్ద చిట్ ‌ లు సమాన నెలవారీ షేర్ ‌ లను ఉపయోగిస్తాయి (విలువ ± నెలలు). కొన్ని గ్రూపులు తక్కువ వాయిదాలను ఉపయోగిస్తాయి (అధిక ప్రారంభ, తక్కువ తరువాత). మీ గుంపుకు సరిపోయే రకాన్ని ఎంచుకోండి.",
  "help.chitMonthsPaid": "మీరు ఇప్పటికే ఎన్ని వాయిదాలను చెల్లించారు. మీరు 46 చెల్లించినట్లయితే, మీరు ఇప్పుడు 47వ నెలలో ఉన్నారు. ఇది బకాయి మొత్తం మరియు నెల సంఖ్యను పరిష్కరిస్తుంది.",
  "help.chitPayoutReceived": "మీరు చిట్ తీసుకున్నప్పుడు మీకు లభించిన అసలు నగదు (ఉదా. ₹ 4,43,000). దీని నుండి వేలం తగ్గింపును మేము రూపొందిస్తాము — మీరు తగ్గింపును ఊహించాల్సిన అవసరం లేదు.",
  "help.chitForeman": "ఆర్గనైజర్ కమీషన్, తరచుగా చిట్ విలువలో 5%, మీరు డబ్బు అందుకున్నప్పుడు కుండ నుండి తీసుకోబడుతుంది.",
  "help.chitDiscount": "వేలంలో మీరు పూర్తి చిట్ విలువ కంటే తక్కువని అంగీకరిస్తారు — ఈ తగ్గింపును ఇతర సభ్యులతో పంచుకుంటారు. మీరు పూర్తి చిట్ మొత్తాన్ని ఎప్పుడూ నగదు రూపంలో స్వీకరించరు.",
  "help.chitAdvisor": "మీరు చిట్ తీసుకోగల నెలలను పోల్చండి: అంచనా వేసిన తగ్గింపు, ఫోర్ ‌ మన్ తర్వాత చెల్లింపు, ఆ నెలలో మీ ఇతర బిల్లులు మరియు మీరు అంగీకరించడానికి సిద్ధంగా ఉన్న గరిష్ట నష్టం.",
  "help.chitMaxLoss": "మీ ఆదాయం, నెలవారీ బకాయిలు, ఓపెన్ డెట్, బకాయి బిల్లులు మరియు పొదుపుల నుండి గరిష్ట నష్టాన్ని మేము సూచిస్తున్నాము — స్థిర % కాదు. ముందస్తుగా తీసుకోవడం తరచుగా దానిని మించిపోతుంది; తరువాత నెలలు సాధారణంగా తక్కువ ఖర్చు అవుతుంది.",
  "help.loanExtraTiming": "రాబోయే నెలలను చూపుతుంది: ఇతర బిల్లులు తేలికగా ఉన్నప్పుడు మీరు ఈ లోన్ ‌ పై అదనంగా చెల్లించవచ్చు మరియు మీరు కనిష్టానికి కట్టుబడి ఉండాల్సిన భారీ నెలలు.",
  "help.incomeEntryBasis": "పన్ను, PF మరియు స్థిర తగ్గింపుల తర్వాత మీ బ్యాంక్‌లో ల్యాండ్ అయ్యే వాటితో టేక్-హోమ్ సరిపోలుతుంది — ఒత్తిడి మరియు ఉచిత నగదు గణన కోసం ఉత్తమమైనది. మీరు నమోదు చేసే ప్రతి సంఖ్య ప్రీ-టాక్స్ అయితే మాత్రమే స్థూల ఉపయోగకరంగా ఉంటుంది; టేక్-హోమ్ ఆదాయం స్థూల కంటే తక్కువగా ఉంటే, ఉచిత నగదు మీ అసలు బ్యాంక్ బ్యాలెన్స్ కంటే తక్కువగా కనిపిస్తుంది.",
  "help.householdPayerBillTag": "ఫ్యామిలీ మోడ్ కోసం ఐచ్ఛికం: ఇంటి పల్స్ స్ప్లిట్ బాధ్యతను వివరించగలదు కాబట్టి ఎవరు చెల్లిస్తారు. మొత్తాలు మరియు పీడన గణితం ఒకే విధంగా ఉంటాయి.",
